import {foods,recipes,days,defaults,meal,plan,sceneInventory,stockStatus} from './model.js';
import {initKitchen} from './kitchen-scene.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD'}).format(n);
const qty=n=>Math.round(n*10)/10;
const foodQty=(n,unit)=>qty(n)+(unit==='kg'?' kg':' × '+unit);
const fresh=()=>({...defaults(),includePlanned:false});
let state=fresh(),selected='spinach',shopKind='main',door=true,review=[],confirmed=false,timer;
const preferred=new URLSearchParams(location.search).get('retailer');
if(['woolworths','newworld'].includes(preferred))$('#demoRetailer').value=preferred;
const scene=initKitchen($('#demoScene'),id=>{selected=id;renderIngredient();scene.setSelected(id);});
function notice(text){clearTimeout(timer);$('#notice').textContent=text;$('#notice').classList.add('visible');timer=setTimeout(()=>$('#notice').classList.remove('visible'),4000);}
function currentShop(){const shops=plan(state).shops;return shops.find(s=>s.kind===shopKind)||shops[0];}
function renderIngredient(){const f=foods.find(x=>x.id===selected),stock=state.inventory.find(x=>x.id===selected);if(!f)return;const projected=sceneInventory(state).find(x=>x.id===selected);const due=stock?stock.due-state.day:null;const status=stock?stockStatus(stock,state.day):null;$('#ingredient').innerHTML=`<div class="ingredient-card"><img src="assets/${f.image}.jpg" alt="${f.name}"><div><strong>${f.name}</strong><small>${projected?foodQty(projected.qty,f.unit)+' projected':stock?'Allocated to earlier meals':'Not in the starting kitchen'}</small></div></div><p>${status==='overdue'?'Past its example planning date. Check the actual label before using.':due===0?'Today is its example planning date.':stock?due+' day'+(due===1?'':'s')+' until its example planning date.':'Included only when needed in the shopping plan.'}</p>`;$('#foodPicks').innerHTML=['spinach','chicken','milk','apple'].map(id=>`<button data-food="${id}" aria-pressed="${selected===id}">${foods.find(f=>f.id===id).name}</button>`).join('');}
function render(){const p=plan(state),s=currentShop();shopKind=s.kind;$('#day').value=state.day;$('#dayName').textContent=days[state.day];$('#away').checked=state.away;$('#topUp').value=state.topDay;$$('[data-kids]').forEach(b=>b.setAttribute('aria-pressed',String(state.kidsHome=== (b.dataset.kids==='true'))));$('#planTotal').textContent=money(p.total);$('#stockValue').textContent=money(p.avoided);$('#household').textContent=state.kidsHome?'1 adult + 2 kids':'1 adult';$('#planDetail').textContent=(state.away?'Five days at home':'Seven days at home')+' · '+(state.topDay==='None'?'one shop':'main shop + top-up');$('#shopChoice').innerHTML=p.shops.map(x=>`<option value="${x.kind}" ${x.kind===shopKind?'selected':''}>${x.day} · ${x.kind==='main'?'main shop':'top-up'}</option>`).join('');$('#shoppingLines').innerHTML=s.items.length?s.items.map(x=>{const f=foods.find(f=>f.id===x.id);return `<div class="shopping-line"><img src="assets/${f.image}.jpg" alt=""><span>${f.name}</span><small>${foodQty(x.qty,f.unit)}</small><b>${money(x.cost)}</b></div>`;}).join(''):'<p class="fine">This shop is already covered by the example kitchen.</p>';$('#shopSubtotal').textContent=money(s.items.reduce((n,x)=>n+x.cost,0));$('#prepareReview').disabled=!s.items.length;const r=meal(state,state.day),away=state.away&&state.day>=5;$('#mealDay').textContent=days[state.day].toUpperCase()+'’S PLAN';$('#mealName').textContent=away?'Out of the kitchen':r.name;$('#mealImage').src='assets/'+(away?'hero':r.image)+'.jpg';$('#mealImage').alt=away?'Fresh produce':r.name+' inspiration';$('#mealReason').textContent=away?'No meals planned at home. The shopping list takes that into account.':r.time+' · Existing stock is allocated before extra ingredients are added to the list.';$('#swapMeal').disabled=away;renderIngredient();scene.setItems(sceneInventory(state));scene.setDay(state.day);scene.setSelected(selected);}
function invalidate(){confirmed=false;$('#receipt').hidden=true;$('#receipt').replaceChildren();$('#reviewGate').hidden=false;$('#reviewConsent').checked=false;$('#confirmReview').disabled=true;}
function renderReview(){const total=review.reduce((n,x)=>n+x.qty*x.price,0);$('#reviewLines').innerHTML=review.map(x=>{const f=foods.find(f=>f.id===x.id);return `<div class="review-line"><span>${f.name}<small>${money(x.price)} / ${f.unit} · example</small></span><input type="number" value="${x.qty}" min="${f.unit==='kg'?'.1':'1'}" max="50" step="${f.unit==='kg'?'.1':'1'}" data-quantity="${f.id}" aria-label="${f.name} quantity"><b>${money(x.qty*x.price)}</b><button data-remove="${f.id}" aria-label="Remove ${f.name}">×</button></div>`;}).join('')||'<p class="fine">No items remain. Close this review and prepare another example shop.</p>';$('#reviewTotal').textContent=money(total);$('#reviewConsent').disabled=!review.length;$('#confirmReview').disabled=!review.length||!$('#reviewConsent').checked||confirmed;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.kids){state.kidsHome=b.dataset.kids==='true';invalidate();render();}if(b.dataset.food){selected=b.dataset.food;renderIngredient();scene.setSelected(selected);}if(b.dataset.view){scene.setView(b.dataset.view);$$('[data-view]').forEach(v=>v.setAttribute('aria-pressed',String(v===b)));}if(b.dataset.remove){review=review.filter(x=>x.id!==b.dataset.remove);invalidate();renderReview();}});
$('#away').onchange=e=>{state.away=e.target.checked;invalidate();render();};$('#topUp').onchange=e=>{state.topDay=e.target.value;invalidate();render();};$('#day').oninput=e=>{state.day=Number(e.target.value);render();};$('#shopChoice').onchange=e=>{shopKind=e.target.value;invalidate();render();};$('#swapMeal').onclick=()=>{state.meals[state.day]=(state.meals[state.day]+1)%recipes.length;invalidate();render();};$('#door').onclick=()=>{door=!door;scene.setDoor(door);$('#door').textContent=door?'Close door':'Open door';$('#door').setAttribute('aria-pressed',String(door));};$('#zoomIn').onclick=()=>scene.zoom(1);$('#zoomOut').onclick=()=>scene.zoom(-1);
$('#resetDemo').onclick=()=>{state=fresh();selected='spinach';shopKind='main';invalidate();render();scene.setView('overview');$$('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view==='overview')));notice('Sample household reset. No personal data is loaded.');};
$('#prepareReview').onclick=()=>{review=currentShop().items.map(x=>({...x}));invalidate();renderReview();$('#reviewDialog').showModal();};$('#closeReview').onclick=()=>$('#reviewDialog').close();$('#reviewConsent').onchange=()=>renderReview();$('#demoRetailer').onchange=()=>{invalidate();renderReview();};
$('#reviewLines').onchange=e=>{const id=e.target.dataset.quantity;if(!id)return;const item=review.find(x=>x.id===id),f=foods.find(x=>x.id===id),n=Number(e.target.value);if(!item)return;invalidate();if(!e.target.value||!Number.isFinite(n)||n<=0||n>50||(f.unit!=='kg'&&!Number.isInteger(n))||(f.unit==='kg'&&Math.abs(n*10-Math.round(n*10))>1e-7)){notice('Use 1–50 whole packs, or 0.1–50 kg in 0.1 kg steps.');}else{item.qty=n;}renderReview();};
$('#confirmReview').onclick=()=>{if(confirmed||!review.length||!$('#reviewConsent').checked)return;confirmed=true;const retailer=$('#demoRetailer').selectedOptions[0].textContent;$('#reviewGate').hidden=true;$('#receipt').hidden=false;$('#receipt').replaceChildren();const title=document.createElement('strong');title.textContent='Demo reviewed. No order placed.';const text=document.createElement('p');text.textContent=`${retailer} · pickup · ${review.length} example lines · ${money(review.reduce((n,x)=>n+x.qty*x.price,0))} illustrative food total.`;const note=document.createElement('small');note.textContent='A connected pilot would verify the exact trolley result, show a receipt and leave checkout with the customer. This demo changed no retailer trolley. Editing this example clears the review.';$('#receipt').append(title,text,note);};
$('#shareDemo').onclick=async()=>{const url=new URL('retailer-demo.html',location.href);const retailer=$('#demoRetailer').value;if(['woolworths','newworld'].includes(preferred))url.searchParams.set('retailer',retailer);try{await navigator.clipboard.writeText(url.href);notice('Demo link copied. It contains no household or account data.');}catch{notice('Copy this page’s address to share the sample demo.');}};
const film=$('#film');function pauseFilm(){film.pause();$('#playFilm').textContent='Play film ▶';$('#playFilm').setAttribute('aria-label','Play kitchen film');}$('#playFilm').onclick=async()=>{if(film.paused){try{await film.play();$('#playFilm').textContent='Pause film Ⅱ';$('#playFilm').setAttribute('aria-label','Pause kitchen film');}catch{notice('Film playback is unavailable. The demo still works.');}}else pauseFilm();};new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)pauseFilm();}).observe(film);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseFilm();});
render();
